	if (unlikely(msr_index == MSR_KVM_INTERNAL_GUEST_SSP))
		return kvm_msr_read(emul_to_vcpu(ctxt), msr_index, pdata);

	return __kvm_emulate_msr_read(emul_to_vcpu(ctxt), msr_index, pdata);
}

